// The release stamp is generated by deploy_velum, not from the viewer clock or
// a live API call. Thus the visible version belongs to the assets actually loaded.
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

export const RELEASE_MARKER = '__VELUM_RELEASE__';
export const REVISION_MARKER = '__VELUM_REV__';
export const CACHE_MARKER = '__VELUM_CACHE__';

export function releaseVersion(date) {
  if (!(date instanceof Date) || !Number.isFinite(date.valueOf())) {
    throw new Error('A valid release instant is required.');
  }
  // Every developer release uses one stable timezone, independent of device
  // locale, GitHub runner timezone or daylight-saving changes elsewhere.
  const entries = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Asia/Kolkata',
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
    hourCycle: 'h23'
  }).formatToParts(date);
  const parts = Object.fromEntries(entries.map(entry => [entry.type, entry.value]));
  return `${parts.year}.${parts.month}.${parts.day}.${parts.hour}${parts.minute}${parts.second}`;
}

export function stampRelease({ html, worker, date, sha, runId = '', attempt = '' }) {
  if (!/^[a-f0-9]{40}$/i.test(sha || '')) {
    throw new Error('A full GitHub commit SHA is required for release provenance.');
  }
  if (!html.includes(RELEASE_MARKER) || !html.includes(REVISION_MARKER)) {
    throw new Error('The Velum HTML release stamp placeholders are missing.');
  }
  const expected = `const CACHE='velum-shell-${CACHE_MARKER}';`;
  if (!worker.includes(expected)) {
    throw new Error('Velum service worker cache release placeholder is missing.');
  }
  const version = releaseVersion(date);
  const revision = sha.slice(0, 8);
  // Run ID and attempt guarantee a new service-worker cache even when the
  // same commit is redeployed within the same second.
  const releaseId = [version.replaceAll('.', ''), revision, String(runId || 'manual'),
    String(attempt || '1')].join('-');
  const stampedHtml = html
    .replaceAll(RELEASE_MARKER, version)
    .replaceAll(REVISION_MARKER, revision);
  const stampedWorker = worker.replaceAll(CACHE_MARKER, releaseId);
  return { html: stampedHtml, worker: stampedWorker, version, revision, releaseId };
}

function execute() {
  const indexPath = resolve('velum-gallery/index.html');
  const workerPath = resolve('velum-gallery/sw.js');
  const stamped = stampRelease({
    html: readFileSync(indexPath, 'utf8'),
    worker: readFileSync(workerPath, 'utf8'),
    date: new Date(),
    sha: process.env.GITHUB_SHA,
    runId: process.env.GITHUB_RUN_ID,
    attempt: process.env.GITHUB_RUN_ATTEMPT
  });
  writeFileSync(indexPath, stamped.html);
  writeFileSync(workerPath, stamped.worker);
  process.stdout.write(
    `Velum release v${stamped.version} IST, commit ${stamped.revision}, worker ${stamped.releaseId}\n`
  );
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  execute();
}
